select n.nspname||'.'||p.proname as fq, pg_get_function_identity_arguments(p.oid) as args, p.prokind as kind, p.prosecdef as secdef, pg_get_function_result(p.oid) as ret, l.lanname as lang, has_function_privilege('authenticated', p.oid, 'EXECUTE') as auth_exec, has_function_privilege('anon', p.oid, 'EXECUTE') as anon_exec, p.oid::int as oid, obj_description(p.oid,'pg_proc') as comentario from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('crm','private','public') order by 1,2
